use vstd::prelude::*;

verus! {

    // Specification for the function that constructs a vector of ones
    fn ones(n: usize) -> (result: Vec<i8>)
        requires
            n <= usize::MAX, // n must be a valid size
        ensures
            result.len() == n, // The length of the result is exactly n
            forall |i: usize| 0 <= i < n ==> result[i] == 1, // Every element is 1
            forall |i: usize, j: usize| 0 <= i < n && 0 <= j < n ==> result[i] == result[j], // All elements are equal
            forall |i: usize| 0 <= i < n ==> result[i] > 0 // Every element is strictly positive
    {
        let mut result = Vec::with_capacity(n); // Create a vector with capacity n
        let mut idx: usize = 0; // Initialize index

        while idx < n
            invariant
                idx <= n,
                result.len() == idx, // The length of the result is equal to the current index
                forall |i: usize| 0 <= i < idx ==> result[i] == 1, // All elements filled so far are 1
            decreases n - idx, // Decreases clause for termination
        {
            result.push(1); // Push 1 into the vector
            idx = idx + 1; // Increment index
        }

        result // Return the constructed vector
    }
}

